const Pessoa = require('../models/Pessoa');
const Memoria = require('../models/Memoria');
const Skill = require('../models/Skill');

async function seedRafael() {
  const name = 'Rafael Almeida';
  console.log('Running seeder for', name);

  const existing = await Pessoa.findOne({ nome: name }).exec();
  if (existing) {
    console.log('Existing Pessoa found — removing associated memories and skills');
    if (Array.isArray(existing.memorias) && existing.memorias.length) {
      await Memoria.deleteMany({ _id: { $in: existing.memorias } });
    }
    if (Array.isArray(existing.skills) && existing.skills.length) {
      await Skill.deleteMany({ _id: { $in: existing.skills } });
    }
    await Pessoa.deleteOne({ _id: existing._id });
    console.log('Existing Pessoa and related docs removed');
  }

  // Prepare memories
  const memoriasData = [
    {
      titulo: 'Nascimento',
      data: new Date('1978-01-01'),
      descricao: 'Nasce Rafael Almeida, filho de uma professora de História e de um técnico em eletrônica. São Paulo, SP.',
      palavraChave: 'nascimento',
      imagem: "",
      imagemMimeType: "image/jpeg",
      integrity: 95,
      nodeColor: 'purple',
    },
    {
      titulo: 'Primeira paixão por números',
      data: new Date('1985-01-01'),
      descricao: 'Aos 7 anos, aprende a fazer contas de cabeça com o pai. Desenvolve fascínio por padrões e problemas matemáticos.',
      palavraChave: 'numeros',
      imagem: "",
      imagemMimeType: "image/jpeg",
      integrity: 85,
      nodeColor: 'blue',
    },
    {
      titulo: 'O acidente na estrada',
      data: new Date('1989-01-01'),
      descricao: 'Aos 11 anos, sofre um acidente de carro durante uma viagem familiar. Sai fisicamente ileso, mas passa a sentir ansiedade intensa ao viajar de carro em estradas.',
      palavraChave: 'acidente',
      imagem: "",
      imagemMimeType: "image/jpeg",
      integrity: 40,
      nodeColor: 'red',
    },
    {
      titulo: 'Uma aluna muda sua perspectiva',
      data: new Date('2017-01-01'),
      descricao: 'Uma aluna que havia reprovado duas vezes em Cálculo consegue finalmente passar. Anos depois, ela retorna para dizer que Rafael foi o professor que a fez acreditar que era capaz de aprender matemática.',
      palavraChave: 'aluna',
      imagem: "",
      imagemMimeType: "imagem/jpeg",
      integrity: 90,
      nodeColor: 'green',
    },
    {
      titulo: 'Vício em vídeos curtos',
      data: new Date('2025-01-01'),
      descricao: 'Vídeos curtos e hiperestímulo enchem sua memória com conhecimentos inúteis.',
      palavraChave: 'videos',
      imagem: "",
      imagemMimeType: "imagem/jpeg",
      integrity: 20,
      nodeColor: 'orange',
    },
  ];

  // Prepare skills
  const skillsData = [
    {
      nome: 'Paixão por artes marciais',
      data: new Date('2013-01-01'),
      nivel: 'avancado',
      categoria: 'habilidade',
      active: true,
      tone: 'maroon',
    },
    {
      nome: 'Viagem para a Itália',
      data: new Date('2018-01-01'),
      nivel: 'experiencia',
      categoria: 'experiencia',
      active: true,
      tone: 'teal',
    },
  ];

  // Insert memories and skills
  const memorias = await Memoria.insertMany(memoriasData);
  const skills = await Skill.insertMany(skillsData);

  // Create Pessoa linking memorias and skills
  const pessoa = new Pessoa({
    nome: name,
    memorias: memorias.map((m) => m._id),
    skills: skills.map((s) => s._id),
  });

  await pessoa.save();

  console.log('Seeder complete for', name);
  return { pessoa, memorias, skills };
}

module.exports = { seedRafael };
